<template><div class="page"><div class="page-header"><div><h1 class="page-title">知识库管理</h1><p class="page-description">管理课程资料、解析状态和向量索引。</p></div><div><el-button @click="router.push('/knowledge/search')"><Search/>检索测试</el-button><el-button type="primary" @click="router.push('/knowledge/upload')"><Upload/>上传文件</el-button></div></div><div class="toolbar card card-body"><el-input v-model="filters.keyword" placeholder="文件名或课程" clearable style="width:240px"/><el-select v-model="filters.course" placeholder="全部课程" clearable style="width:180px"><el-option v-for="c in store.courses" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="filters.status" placeholder="全部状态" clearable style="width:150px"><el-option v-for="s in statuses" :key="s" :label="s" :value="s"/></el-select><el-button @click="load">查询</el-button></div><div class="card"><PageState :loading="loading" :error="error" :empty="!items.length" empty-text="还没有知识库文件。" @retry="load"><el-table :data="items"><el-table-column prop="original_name" label="文件名" min-width="210" show-overflow-tooltip/><el-table-column prop="course_name" label="课程" width="150"/><el-table-column prop="file_type" label="类型" width="75"/><el-table-column label="大小" width="90"><template #default="s">{{size(s.row.file_size)}}</template></el-table-column><el-table-column prop="char_count" label="字符数" width="90"/><el-table-column prop="chunk_count" label="文本块" width="80"/><el-table-column label="解析进度" width="150"><template #default="s"><el-progress :percentage="s.row.parse_progress" :status="s.row.parse_status==='FAILED'?'exception':s.row.parse_status==='SUCCESS'?'success':''"/></template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><StatusTag :value="s.row.parse_status"/></template></el-table-column><el-table-column label="上传时间" width="165"><template #default="s">{{fmt(s.row.created_at)}}</template></el-table-column><el-table-column label="操作" width="260" fixed="right"><template #default="s"><el-button link type="primary" @click="router.push(`/knowledge/files/${s.row.id}`)">详情</el-button><el-button link @click="reparse(s.row)">重新解析</el-button><el-button link @click="toggle(s.row)">{{s.row.is_enabled?'停用':'启用'}}</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="load"/></PageState></div></div></template>
<script setup>import{ref,reactive,onMounted}from'vue';import{useRouter,useRoute}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{knowledgeApi}from'../../api';import{useAppStore}from'../../stores/app';import PageState from'../../components/PageState.vue';import StatusTag from'../../components/StatusTag.vue';const router=useRouter(),route=useRoute(),store=useAppStore(),items=ref([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(''),filters=reactive({keyword:'',course:'',status:route.query.status||''}),statuses=['WAITING','PARSING','CLEANING','CHUNKING','VECTORIZING','SUCCESS','FAILED','DISABLED','INTERRUPTED'];const fmt=x=>new Date(x).toLocaleString('zh-CN',{hour12:false}),size=n=>n>1048576?(n/1048576).toFixed(1)+' MB':(n/1024).toFixed(1)+' KB';const load=async()=>{loading.value=true;error.value='';try{const d=await knowledgeApi.files({...filters,page:page.value});items.value=d.items;total.value=d.total}catch(e){error.value=e.message}finally{loading.value=false}};const reparse=async r=>{await knowledgeApi.reparse(r.id);ElMessage.success('已加入解析队列');load()};const toggle=async r=>{r.is_enabled?await knowledgeApi.disable(r.id):await knowledgeApi.enable(r.id);ElMessage.success('状态已更新');load()};const remove=async r=>{await ElMessageBox.confirm('删除后会同步清理该文件的文本块和向量记录。是否继续？','删除知识库文件',{type:'warning'});await knowledgeApi.remove(r.id);ElMessage.success('文件已删除');load()};onMounted(()=>{store.loadCourses();load()})</script>
